#!/usr/bin/env python3
"""Four indexed configs: compare regenerated bytes, never parse historical YAML.

The canonical payload must already exist in the exact indexed producer JSON
manifest. Missing producer JSON is a recorded failure, not permission to load
YAML or substitute another slot. This is not a historical/media freshness pass.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import re
from pathlib import Path

from evicastkv_review_followups import cpu_gate

from mosaickv.evaluation.fox_campaign import clean_source, digest, sha, write_once

SOURCE = Path(__file__).resolve().parents[2]
WORKSPACE = Path("/scratch/djy8hg/workdir").resolve()
HISTORY = Path("/scratch/djy8hg/runs/mosaickv").resolve()
DEFAULT_CAMPAIGN = HISTORY / "main-quality-campaigns/main-quality-v2-1ed3ae4"
DEFAULT_INVENTORY = Path(
    "/scratch/djy8hg/audits/fox-review-v8-consumed-diagnostics-20261110/"
    "freshness-continuation/aggregate/inventory.json"
)
SLOTS = ((0, "mmstar"), (8, "textvqa"), (33, "docvqa"), (60, "chartqa"))
YAML_GAP = "YAML requires separately reviewed lexical identity projection"
MAX_INDEX_BYTES = 32 * 2**20
MAX_INVENTORY_BYTES = 64 * 2**20
MAX_METADATA_BYTES = 2**20


def hash_bytes(data):
    return hashlib.sha256(data).hexdigest()


def read_bytes(path, *, bound=MAX_METADATA_BYTES, expected=None):
    """Stable, bounded reads; no glob, tree walk or dataset access."""
    path = Path(path)
    before = path.stat()
    if before.st_size > bound:
        raise ValueError("bound producer artifact exceeds registered byte limit")
    with path.open("rb") as handle:
        value = handle.read(bound + 1)
    after = path.stat()
    if len(value) != before.st_size or (before.st_ino, before.st_size, before.st_mtime_ns) != (
        after.st_ino,
        after.st_size,
        after.st_mtime_ns,
    ):
        raise ValueError("bound producer artifact changed during read")
    actual = hash_bytes(value)
    if expected is not None and actual != expected:
        raise ValueError("immutable producer artifact hash changed")
    return value, actual


def read_json(data):
    def unique(pairs):
        result = {}
        for key, value in pairs:
            if key in result:
                raise ValueError("duplicate key in bound producer JSON")
            result[key] = value
        return result

    return json.loads(data, object_pairs_hook=unique)


def under_history(path):
    actual = Path(path).resolve(strict=True)
    if not actual.is_relative_to(HISTORY) or not actual.is_file():
        raise ValueError("producer artifact escapes the registered historical root")
    return actual


def prepare(parent, inventory_path, inventory_sha256):
    parent = Path(parent).resolve(strict=True)
    if not parent.is_relative_to(HISTORY):
        raise ValueError("campaign escapes registered history")
    matrix_path = under_history(parent / "matrix_manifest.json")
    matrix_raw, matrix_sha = read_bytes(matrix_path)
    matrix = read_json(matrix_raw)
    index_path = under_history(parent / "jobs.jsonl")
    index_raw, index_sha = read_bytes(
        index_path, bound=MAX_INDEX_BYTES, expected=matrix["index_sha256"]
    )
    lines = index_raw.splitlines()
    if len(lines) != matrix["job_count"] or not 1 <= len(lines) <= 10000:
        raise ValueError("indexed campaign row count differs or exceeds bound")
    inventory_raw, inventory_sha = read_bytes(
        inventory_path, bound=MAX_INVENTORY_BYTES, expected=inventory_sha256
    )
    inventory = read_json(inventory_raw)
    gaps = {r["path"]: r for r in inventory["errors"] if r.get("error") == YAML_GAP}
    selected = []
    for index, task in SLOTS:
        row = read_json(lines[index])
        if row["array_index"] != index or row["task_key"] != task:
            raise ValueError("fixed producer canary index/task changed")
        if row["config_path"] not in gaps:
            raise ValueError("fixed slot is not a recorded unsupported-YAML gap")
        selected.append(dict(row=row, original_error_sha256=digest(gaps[row["config_path"]])))
    return dict(
        campaign=str(parent),
        matrix=matrix,
        slots=selected,
        bindings={
            str(matrix_path): matrix_sha,
            str(index_path): index_sha,
            str(inventory_path): inventory_sha,
        },
        original_errors_sha256=digest(inventory["errors"]),
        original_error_count=len(inventory["errors"]),
        cohort_selected=False,
        fresh_confirmation_authorized=False,
        materialization_authorized=False,
    )


def verify_slot(item, plan):
    import yaml

    if yaml.__version__ != "6.0.3":
        raise ValueError("canary requires the pinned PyYAML 6.0.3 serializer")
    row, matrix = item["row"], plan["matrix"]
    parent = Path(plan["campaign"])
    config_sha, index, shard_index = row["config_sha"], row["array_index"], row["shard_index"]
    if not re.fullmatch(r"[0-9a-f]{64}", config_sha):
        raise ValueError("indexed canonical config digest is invalid")
    name = f"{index:06d}-{config_sha}-{shard_index:05d}.yaml"
    config = under_history(row["config_path"])
    if config != parent / "configs" / name:
        raise ValueError("indexed generated-config path changed")
    if row["output_root"] != matrix["output_root"] or not re.fullmatch(r"[\w-]+", row["run_id"]):
        raise ValueError("indexed producer output path changed")
    manifest_path = Path(matrix["output_root"]).resolve() / row["run_id"] / "manifest.json"
    if under_history(manifest_path) != manifest_path:
        raise ValueError("producer manifest redirects outside its indexed location")
    manifest_raw, manifest_sha = read_bytes(manifest_path)
    manifest = read_json(manifest_raw)
    source, payload = manifest["source"], manifest["resolved_config"]
    if (
        manifest["run_id"] != row["run_id"]
        or source["git_sha"] != matrix["source_git_sha"]
        or source["git_dirty"] is not False
        or source["config_sha"] != config_sha
        or not isinstance(payload, dict)
    ):
        raise ValueError("canonical indexed producer JSON provenance differs")
    canonical = json.dumps(
        payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False
    ).encode()
    if hash_bytes(canonical) != config_sha:
        raise ValueError("saved producer JSON payload does not match the indexed canonical digest")
    # Serialization only. The historical YAML is never passed to any loader.
    reconstructed = yaml.safe_dump(payload, sort_keys=True).encode()
    actual_yaml, yaml_sha = read_bytes(config)
    if reconstructed != actual_yaml:
        raise ValueError("safe_dump bytes differ from the indexed historical YAML")

    ledger_ref = matrix["sample_ledgers"][row["task_key"]]
    if (row["full_sample_ledger_path"], row["full_sample_ledger_sha"]) != (
        ledger_ref["path"],
        ledger_ref["sha256"],
    ):
        raise ValueError("index and matrix ledger bindings differ")
    ledger_path = under_history(ledger_ref["path"])
    ledger_raw, ledger_sha = read_bytes(ledger_path, expected=ledger_ref["sha256"])
    ledger = read_json(ledger_raw)
    shard_path = under_history(row["sample_id_file"])
    if shard_path != parent / "sample_shards" / row["task_key"] / f"{shard_index:05d}.json":
        raise ValueError("indexed sample shard redirects from its registered path")
    shard_raw, shard_sha = read_bytes(shard_path, expected=row["sample_id_file_sha"])
    shard = read_json(shard_raw)
    identity = {key: ledger[key] for key in ("dataset_id", "dataset_revision", "split", "task")}
    if any(shard[key] != value for key, value in identity.items()):
        raise ValueError("sample shard dataset provenance differs from parent ledger")
    dataset = dict(
        id=identity["dataset_id"], revision=identity["dataset_revision"], split=identity["split"]
    )
    if (
        manifest["dataset"] != dataset
        or payload["dataset"] != dataset
        or identity["task"] != row["task"]
    ):
        raise ValueError("config/manifest/ledger dataset provenance differs")
    ids = ledger["sample_ids"]
    if not all(isinstance(value, str) for value in ids) or len(set(ids)) != len(ids):
        raise ValueError("parent ledger is not a unique ID-only list")
    if len(ids) != ledger["sample_count"]:
        raise ValueError("parent ledger ID count differs")
    ids = ids[: matrix["sample_limit"]] if matrix["sample_limit"] is not None else ids
    size = matrix["shard_size"]
    if (
        shard["parent_ledger_sha"] != ledger_sha
        or shard["shard_index"] != shard_index
        or shard["shard_count"] != row["shard_count"]
        or shard["shard_count"] != (len(ids) + size - 1) // size
        or not 0 <= shard_index < shard["shard_count"]
        or shard["sample_ids"] != ids[shard_index * size : (shard_index + 1) * size]
    ):
        raise ValueError("sample shard is not the exact indexed parent-ledger slice")
    diagnostics = payload["diagnostics"]
    expected_diagnostic = ids[: min(matrix["diagnostic_size"], len(ids))]
    if (
        diagnostics["sample_ids"] != expected_diagnostic
        or diagnostics["sample_ledger_sha"] != ledger_sha
        or row["diagnostic_sample_count"] != len(expected_diagnostic)
    ):
        raise ValueError("producer config diagnostic IDs lack exact parent-ledger binding")
    return dict(
        status="verified_producer_bound_generated_config",
        indexed_config_sha256=config_sha,
        historical_yaml_sha256=yaml_sha,
        regenerated_yaml_sha256=hash_bytes(reconstructed),
        producer_manifest_path=str(manifest_path),
        producer_manifest_sha256=manifest_sha,
        producer_source_sha=source["git_sha"],
        parent_ledger_path=str(ledger_path),
        parent_ledger_sha256=ledger_sha,
        shard_path=str(shard_path),
        shard_sha256=shard_sha,
        dataset=dataset,
        shard_identity_count=len(shard["sample_ids"]),
        serializer=yaml.__version__,
        identities_exported=False,
        error_waived=False,
    )


def run(
    root,
    parent=DEFAULT_CAMPAIGN,
    *,
    cpu_gate_root=None,
    inventory_sha256=None,
    inventory_path=DEFAULT_INVENTORY,
):
    if cpu_gate_root is None or inventory_sha256 is None:
        raise ValueError("verified CPU gate and explicit inventory SHA required")
    root = Path(root).resolve()
    if root.exists() or not root.is_relative_to(WORKSPACE):
        raise ValueError("new immutable workspace output required")
    revision = clean_source(SOURCE)
    cpu = cpu_gate(Path(cpu_gate_root), revision)
    plan = prepare(parent, inventory_path, inventory_sha256)
    plan.update(source_sha=revision, cpu_gate=cpu)
    write_once(root / "plan.json", plan)
    observations = []
    for item in plan["slots"]:
        row = item["row"]
        record = dict(
            index=row["array_index"],
            task=row["task_key"],
            config_path=row["config_path"],
            original_error_sha256=item["original_error_sha256"],
        )
        try:
            record.update(verify_slot(item, plan))
        except (OSError, KeyError, TypeError, ValueError, ZeroDivisionError) as exc:
            record.update(status="blocked_not_waived", error=f"{type(exc).__name__}: {exc}")
        write_once(root / f"config-{row['array_index']:06d}.json", record)
        observations.append(record)
    verified = sum(
        row["status"] == "verified_producer_bound_generated_config" for row in observations
    )
    gate = dict(
        status="completed_producer_bound_config_canary"
        if verified == len(SLOTS)
        else "blocked_producer_bound_config_canary",
        source_sha=revision,
        plan_sha256=sha(root / "plan.json"),
        selected=len(SLOTS),
        verified=verified,
        rows=observations,
        historical_yaml_parsed=False,
        new_historical_scan_performed=False,
        original_error_count=plan["original_error_count"],
        original_errors_preserved=True,
        error_waivers=0,
        complete_historical_id_inventory=False,
        cross_dataset_media_certified=False,
        fresh_confirmation_authorized=False,
        materialization_authorized=False,
        cohort_selected=False,
    )
    write_once(root / "GATE_freshness_producer_canary.json", gate)
    return gate


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, required=True)
    parser.add_argument("--parent", type=Path, default=DEFAULT_CAMPAIGN)
    parser.add_argument("--cpu-gate-root", type=Path)
    parser.add_argument("--inventory-sha256")
    parser.add_argument("--execute", action="store_true")
    args = parser.parse_args()
    result = (
        run(
            args.root,
            args.parent,
            cpu_gate_root=args.cpu_gate_root,
            inventory_sha256=args.inventory_sha256,
        )
        if args.execute
        else dict(status="dry_run_only", selected_slots=SLOTS, execution_performed=False)
    )
    print(json.dumps(result))
